def task(robot):
    # 1. Look at the cans to determine available colors
    cans = robot.look()
    available_colors = set(can['colour'] for can in cans)

    if not available_colors:
        robot.say("I'm sorry, there are no drinks available right now.")
        return

    # 2. Ask the guest which color they would like
    robot.say("Hello! Which color drink would you like?")
    guest_choice = robot.listen()

    # Simple parsing to extract the color (assuming the guest says something like "blue" or "red")
    # In a real scenario, this would require more robust NLP.
    target_color = None
    for color in available_colors:
        if color.lower() in guest_choice.lower():
            target_color = color
            break

    if target_color:
        # 3. Find a can of the target color
        target_can_id = None
        for can in cans:
            if can['colour'] == target_color:
                target_can_id = can['id']
                break

        if target_can_id is not None:
            # 4. Pick the can
            if robot.pick(target_can_id):
                robot.say(f"Here is your {target_color} drink.")
                # 5. Give the can to the guest
                if robot.give():
                    robot.wave()
                else:
                    robot.say("I picked it up, but I couldn't hand it over.")
            else:
                robot.say("I couldn't pick up the requested can.")
        else:
            # This case should ideally not happen if available_colors was correct, but as a fallback:
            robot.say(f"I'm sorry, I couldn't find a {target_color} drink.")
    else:
        # 6. If no can of that color exists
        robot.say(f"Sorry, I don't have a {guest_choice} drink available.")

def task(robot):
    cans = robot.look()
    if not cans:
        robot.say("No cans found on the table.")
        return

    # Sort cans by their x-coordinate (distance from robot's center).
    # The robot's center is at x=0.
    # Furthest to the robot's right means the largest positive x value.
    # We want to process them from largest positive x to largest negative x.
    sorted_cans = sorted(cans, key=lambda can: can['x'], reverse=True)

    for can in sorted_cans:
        can_id = can['id']
        robot.say(f"Picking can {can_id}.")
        if robot.pick(can_id):
            robot.say(f"Moving can {can_id} to the tray.")
            # Assuming 'tray' is a valid spot for placing cans
            if robot.place("tray"):
                robot.say(f"Can {can_id} placed on the tray.")
            else:
                robot.say(f"Error placing can {can_id} on the tray.")
        else:
            robot.say(f"Could not pick can {can_id}. Skipping.")

