def task(robot):
    cans = robot.look()
    if len(cans) < 2:
        robot.say("Sorry, I only see one can.")
        return

    # Find two cans of different colors
    can1_id = -1
    can2_id = -1
    colors_seen = set()

    for can in cans:
        if can['colour'] not in colors_seen:
            if can1_id == -1:
                can1_id = can['id']
                colors_seen.add(can['colour'])
            elif can2_id == -1:
                can2_id = can['id']
                colors_seen.add(can['colour'])
                break

    if can1_id != -1 and can2_id != -1:
        robot.say(f"I will give you the {cans[can1_id]['colour']} and the {cans[can2_id]['colour']}.")

        # Pick the first can
        if robot.pick(can1_id):
            robot.say(f"Picking the {cans[can1_id]['colour']} can.")

            # Give the first can
            if robot.give():
                robot.say(f"Here is the {cans[can1_id]['colour']} can.")
                # Place the first can down (optional, but good practice if the guest expects it)
                robot.place("table")

            # Pick the second can
            if robot.pick(can2_id):
                robot.say(f"Picking the {cans[can2_id]['colour']} can.")

                # Give the second can
                if robot.give():
                    robot.say(f"And here is the {cans[can2_id]['colour']} can.")
                    # Place the second can down
                    robot.place("table")
            else:
                robot.say("Error: Could not pick the second can.")
        else:
            robot.say("Error: Could not pick the first can.")
    else:
        robot.say("I could not find two cans of different colors to give you.")

def task(robot):
    cans = robot.look()
    if not cans:
        robot.say("I don't see any drinks on the table.")
        return

    # Find the Sprite can closest to the robot (minimum absolute x distance)
    sprite_can = None
    min_distance = float('inf')

    for can in cans:
        if "Sprite" in can["label"]:
            distance = abs(can["x"])
            if distance < min_distance:
                min_distance = distance
                sprite_can = can

    if sprite_can:
        robot.say(f"Here is the Sprite.")
        robot.pick(sprite_can["id"])
        robot.give()
        robot.place("tray")
    else:
        robot.say("I'm sorry, I don't see any Sprite cans here.")
